const raw = $json.text || '';
const cleaned = raw.split(/On .+wrote:/s)[0].trim();

return [{
  json: {
    message: cleaned,
    from_email: $json.from.value[0].address,
    from_name: $json.from.value[0].name,
    subject: $json.subject
  }
}];

const aiOutput = $json.output[0].content[0].text;
const original = $('Find Request').item.json.fields;

return [{
  json: {
    feedback_id: original['Feedback ID'],
    job_id: original['Job ID'],
    customer_id: original['Customer ID'],
    customer_name: original['Customer Name'],
    location: original['Location'],
    message: $('Code in JavaScript').item.json.message,
    sentiment_score: aiOutput.sentiment_score,
    severity: aiOutput.severity,
    confidence: aiOutput.confidence,
    category: aiOutput.category,
    summary: aiOutput.summary
  }
}];

const scored = $('Code in JavaScript1').item.json;

const historyResults = $('Search records1').all().filter(item => item.json.id);
const priorNegativeCount = historyResults.length;
const isRepeatOffender = priorNegativeCount >= 1;

const hasIssue = ['low', 'medium', 'high'].includes(scored.severity);

let routing;
if (scored.severity === 'high') {
  routing = 'escalate';
} else if (isRepeatOffender && (hasIssue || scored.sentiment_score <= 0.2)) {
  routing = 'escalate';
} else if (scored.sentiment_score > 0.2 && !hasIssue) {
  routing = 'ready_to_post';
} else {
  routing = 'private_queue';
}

return [{
  json: {
    ...scored,
    prior_negative_count: priorNegativeCount,
    is_repeat_offender: isRepeatOffender,
    routing
  }
}];

